# Small-Stings create a payable (Bill, 2026-10-22): Dr 6550-small_sting_expense /
# Cr 2230-small_stings_payable. A fresh install gets both accounts and both roles from
# seed_gl_accounts. An installed chart gets them here, so filing a sting on an existing
# install does not refuse for a role nobody mapped. Only what is missing is added: an
# account that exists and a role the company already mapped are never touched.
STING_ACCOUNTS = (
    ('2230-small_stings_payable', 'Small-Stings Payable', 'liability', 'current_liabilities', 'payables'),
    ('6550-small_sting_expense', 'Small-Sting Expense', 'expense', 'operating_expenses', 'expense'),
)
STING_ROLES = {
    'small_stings_payable': '2230-small_stings_payable',
    'small_sting_expense': '6550-small_sting_expense',
}


def add_sting_accounts_and_roles(apps, schema_editor):
    GlAccount = apps.get_model('accounts', 'GlAccount')
    Setting = apps.get_model('core', 'Setting')
    if not GlAccount.objects.exists():
        return                      # no chart yet: seed_gl_accounts brings both
    for ida, name, acct_type, category, used_for in STING_ACCOUNTS:
        if not GlAccount.objects.filter(ida=ida).exists():
            GlAccount.objects.create(ida=ida, name=name, type=acct_type, category=category,
                                     used_for=used_for, is_active=True)
    for company in Setting.objects.filter(purpose='wc:company_profile'):
        config = company.config if isinstance(company.config, dict) else {}
        defaults = config.get('gl_defaults')
        if not isinstance(defaults, dict) or not defaults:
            continue                # no role map: WC_HQ's recommended set fills it
        missing = {role: code for role, code in STING_ROLES.items() if not defaults.get(role)}
        if missing:
            config['gl_defaults'] = {**defaults, **missing}
            Setting.objects.filter(pk=company.pk).update(config=config)


